     *
     * Enables or disables startElement parsing.
     */
    void  enable_startElementenable_startElement(bool  enable);

    /**
     * enable_endRoot
     * @param enable bool indicate enable or disable SAX parsing.
     *
     * Enables or disables endRoot parsing.
     */
    void  enable_endRootenable_endRoot(bool  enable);

    /**
     * enable_endUnit
     * @param enable bool indicate enable or disable SAX parsing.
     *
     * Enables or disables endUnit parsing.
     */
    void  enable_endUnitenable_endUnit(bool  enable);


    /**
