     *
     * Internally used to increment the count in SAX2srcSAXHandler.
     */
    /**unclassified */
    void  increment_unit_countincrement_unit_count() {

        ++unit_count;

    }

    /**
     * get_stack
     *
     * Used internally to update the stack.
     */
    /**nonconstget */
    std::vector<std::string> &  get_stack() {

        return srcml_element_stack;

    }

    /**
     * get_controller
     *
     * Get the control handler.
     */
    /**collaborator */
    srcSAXController &  get_controllerget_controller() {

        return *controller;

    }

