function.block:
{

  if(argc < 2) {

    std::cerr << "Useage: element_count input_file.xml\n";
    exit(1);

  }

  srcSAXController  control(argv[1]);
  element_count_handler  handler;
  control.parseparseparse(&handlerparse);

  for(std::map<std::string, unsigned long long>::const_iterator  citr = handler.get_countsget_counts().begin(); citr != handler.get_countsget_counts().end(); ++citr) {

  	std::cout << citr->first << ": " << citr->second << '\n';

  }

  return 0;
}

