class element_count_handler : public srcSAXHandler {

private :

    /** map to count srcML elements */
    std::map<std::string, unsigned long long>  element_counts;

public :

#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wunused-parameter"

    /**
     * get_counts
     *
     * Accessor method to get the element counts.
     *
     * @returns the element count map.
     */
    /**get */
    const std::map<std::string, unsigned long long> &  get_counts() const {

        return element_counts;

    }

    /**
     * update_count
     * @param prefix the element's prefix
     * @param localname the element name
     *
     * Helper function to update the count of an element or add it if necessary.
     * Need the full name (prefix + localname) of elemement to disambiguate between
     * elements with the same name, but different prefix/namespaces (e.g. cpp:if, if).
     * A more general find approach is used instead of relying on access using the
     * operator[] to default non-existant items to 0. 
     */
    /**command */
    void  update_countupdate_count(const char *  prefix, const char *  localname) {

        std::string  element = "";
        if(prefix) {

            element += (const char *)prefix;
            element += ":";

        }
        element += (const char *)localname;

        /* Note: in map could just use operator[], however, this a bit more general */
        std::map<std::string, unsigned long long>::iterator  itr = element_counts.find(element);
        if(itr == element_counts.end()) {

            element_counts.insert(std::pair<std::string, unsigned long long>(element, 1));

        } else {

            ++itr->second;

        }

    }

    /*
    virtual void startDocument() {}
    virtual void endDocument() {}
    */

    /**
     * startRoot
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     * @param num_namespaces number of namespaces definitions
     * @param namespaces the defined namespaces
     * @param num_attributes the number of attributes on the tag
     * @param attributes list of attributes
     *
     * SAX handler function for start of the root element.
     * Counts the root unit (if an archive, to avoid double count with startUnit).
     * Overide for desired behaviour.
     */
    /**command collaborator */
    virtual void  startRoot(const char *  localname, const char *  prefix, const char *  URI,
                           int  num_namespaces, const struct srcsax_namespace *  namespaces, int  num_attributes,
                           const struct srcsax_attribute *  attributes) {

        if(is_archive)
            update_count(prefix, localname);

    }

    /**
     * startUnit
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     * @param num_namespaces number of namespaces definitions
     * @param namespaces the defined namespaces
     * @param num_attributes the number of attributes on the tag
     * @param attributes list of attributes
     *
     * SAX handler function for start of an unit.
     * Counts each unit tag (= filecount non-archive, = filecount + 1 if archive).
     * Overide for desired behaviour.
     */
    /**command collaborator stateless */
    virtual void  startUnitstartUnit(const char *  localname, const char *  prefix, const char *  URI,
                           int  num_namespaces, const struct srcsax_namespace *  namespaces, int  num_attributes,
                           const struct srcsax_attribute *  attributes) {

            update_count(prefix, localname);

    }

    /**
     * startElement
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     * @param num_namespaces number of namespaces definitions
     * @param namespaces the defined namespaces
     * @param num_attributes the number of attributes on the tag
     * @param attributes list of attributes
     *
     * SAX handler function for start of an element.
     * Count each element.
     * Overide for desired behaviour.
     */
    /**command collaborator stateless */
    virtual void  startElementstartElement(const char *  localname, const char *  prefix, const char *  URI,
                                int  num_namespaces, const struct srcsax_namespace *  namespaces, int  num_attributes,
                                const struct srcsax_attribute *  attributes) {

        update_count(prefix, localname);

    }

    /*

    // end elements may need to be used if you want to collect only on per file basis or some other granularity.
    virtual void endRoot(const char * localname, const char * prefix, const char * URI) {}
    virtual void endUnit(const char * localname, const char * prefix, const char * URI) {}
    virtual void endElement(const char * localname, const char * prefix, const char * URI) {}

    // Contains information such as stuff used for parsing.  So, probably do not need to count.
    virtual void metaTag(const char* localname, const char* prefix, const char* URI, int num_namespaces, const char** namespaces, int num_attributes, const char** attributes) {}

    // Not typically in srcML documents    
    virtual void comment(const char * value) {}
    virtual void cdataBlock(const char * value, int len) {}
    virtual void processingInstruction(const char * target, const char * data) {}
    */

#pragma GCC diagnostic pop

};

class identity_copy_handler : public srcSAXHandler {

private :

    xmlTextWriterPtr  writer;
    std::string  content;

public :

    /**
     * identity_copy_handler
     *
     * Constructor.  Open xmlwriter. 
     */
    identity_copy_handler(std::string  output_filename) : writer(0) {

        if((writer = xmlNewTextWriterFilename(output_filename.c_str(), 0)) == 0) {

            std::cerr << "Problems opening output file: " << output_filename << '\n';
            exit(1);

        }

    }

    /**
     * ~identity_copy_handler
     *
     * Destructor. Free writer resource.
     */
    ~identity_copy_handler() {

        if(writer)
            xmlFreeTextWriter(writer);

    }

#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wunused-parameter"

    /**
     * startDocument
     *
     * SAX handler function for start of document.
     * Write start of xml document.
     *
     * Overide for desired behaviour.
     */
    /**command */
    virtual void  startDocumentstartDocument() {

        xmlTextWriterStartDocument(writer, "1.0", "UTF-8", "yes");

    }

    /**
     * endDocument
     *
     * SAX handler function for end of document.
     * Write the end of xml document.
     *
     * Overide for desired behaviour.
     */
    /**command */
    virtual void  endDocumentendDocument() {

        xmlTextWriterEndDocument(writer);

    }

    /**
     * write_start_tag
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     * @param num_namespaces number of namespaces definitions
     * @param namespaces the defined namespaces
     * @param nb_attributes the number of attributes on the tag
     * @param attributes list of attributes
     *
     * SAX handler function for start of the root element.
     * Write out a start tag.
     *
     * Overide for desired behaviour.
     */
    /**command collaborator */
    void  write_start_tagwrite_start_tag(const char*  localname, const char*  prefix, const char*  URI,
                           int  num_namespaces, const struct srcsax_namespace *  namespaces, int  num_attributes,
                           const struct srcsax_attribute *  attributes) {

        xmlTextWriterStartElementNS(writer, (const xmlChar *)prefix, (const xmlChar *)localname, 0);

        for(int  pos = 0; pos < num_namespaces; ++pos) {

            std::string  name = "xmlns";
            if(namespaces[pos].prefix) {
                name += ":";

                name += (const char *)namespaces[pos].prefix;

            }

            xmlTextWriterWriteAttribute(writer, (const xmlChar *)name.c_str(), (const xmlChar *)namespaces[pos].uri);

        }

        for(int  pos = 0; pos < num_attributes; ++pos) {

            xmlTextWriterWriteAttributeNS(writer, (const xmlChar *)attributes[pos].prefix, (const xmlChar *)attributes[pos].localname,
                (const xmlChar *)attributes[pos].uri, (const xmlChar *)attributes[pos].value);

        }

    }

    /**
     * write_content
     * @param text_content
     *
     * Write out the provided text content, escaping everything but ".
     */
    /**command */
    void  write_contentwrite_content(std::string &  text_content) {

        if(text_content != "") {

            /*
                Normal output of text is for the most part
                identical to what libxml2 provides.  However,
                srcML does not escape " while libxml2 does escape
                quotations.
            */
            int  ret = 0;
            char *  text = (char *)text_content.c_str();
            for(char *  pos = text; *pos; ++pos) {

              if(*pos != '"') continue;

              *pos = 0;
              ret = xmlTextWriterWriteString(writer, (const xmlChar *)text);
              //if(ret == -1) return false;

              *pos = '\"';
              xmlTextWriterWriteRaw(writer, (const xmlChar *)"\"");
              //if(ret == -1) return false;

              text = pos + 1;

            }

            ret = xmlTextWriterWriteString(writer, (const xmlChar *)text);

            text_content = "";

        }

    }

    /**
     * startRoot
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     * @param num_namespaces number of namespaces definitions
     * @param namespaces the defined namespaces
     * @param nb_attributes the number of attributes on the tag
     * @param attributes list of attributes
     *
     * SAX handler function for start of the root element.
     * Write out the root start tag (unless non-archive, startUnit will handle).
     *
     * Overide for desired behaviour.
     */
    /**command collaborator */
    virtual void  startRootstartRoot(const char*  localname, const char*  prefix, const char*  URI,
                           int  num_namespaces, const struct srcsax_namespace *  namespaces, int  nb_attributes,
                           const struct srcsax_attribute *  attributes) {

        if(is_archive)
            write_start_tag(localname, prefix, URI, num_namespaces, namespaces, nb_attributes, attributes);

    }

    /**
     * startUnit
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     * @param num_namespaces number of namespaces definitions
     * @param namespaces the defined namespaces
     * @param nb_attributes the number of attributes on the tag
     * @param attributes list of attributes
     *
     * SAX handler function for start of an unit.
     * Write out any saved text, then write out the unit tag.
     *
     * Overide for desired behaviour.
     */
    /**command collaborator */
    virtual void  startUnitstartUnit(const char*  localname, const char*  prefix, const char*  URI,
                           int  num_namespaces, const struct srcsax_namespace *  namespaces, int  nb_attributes,
                           const struct srcsax_attribute *  attributes) {

        // write out buffered root level characters
        write_content(content);

        write_start_tag(localname, prefix, URI, num_namespaces, namespaces, nb_attributes, attributes);

    }

    /**
     * startElement
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     * @param num_namespaces number of namespaces definitions
     * @param namespaces the defined namespaces
     * @param nb_attributes the number of attributes on the tag
     * @param attributes list of attributes
     *
     * SAX handler function for start of an element.
     * Write out any saved text, then write out the elementtag.
     * 
     * Overide for desired behaviour.
     */
    /**command collaborator */
    virtual void  startElementstartElement(const char*  localname, const char*  prefix, const char*  URI,
                                int  num_namespaces, const struct srcsax_namespace *  namespaces, int  nb_attributes,
                                const struct srcsax_attribute *  attributes) {

        // write out buffered characters
        write_content(content);

        write_start_tag(localname, prefix, URI, num_namespaces, namespaces, nb_attributes, attributes);

    }

    /**
     * endRoot
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     *
     * SAX handler function for end of the root element.
     * Write out any saved content, then end the root tag.
     *
     * Overide for desired behaviour.
     */
    /**command */
    virtual void  endRootendRoot(const char*  localname, const char*  prefix, const char*  URI) {

        // write out buffered root level characters
        if(is_archive) {

            write_content(content);

            xmlTextWriterEndElement(writer);

        }

    }

    /**
     * endUnit
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     *
     * SAX handler function for end of an unit.
     * Write out any saved up content, then write out ending unit tag.
     *
     * Overide for desired behaviour.
     */
    /**command */
    virtual void  endUnitendUnit(const char*  localname, const char*  prefix, const char*  URI) {

        // write out any buffered characters
        write_content(content);

        xmlTextWriterEndElement(writer);

    }

    /**
     * endElement
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     *
     * SAX handler function for end of an element.
     * Write out any saved content, then write out ending element tag.
     *
     * Overide for desired behaviour.
     */
    /**command */
    virtual void  endElementendElement(const char*  localname, const char*  prefix, const char*  URI) {

        // write out any buffered characters
        write_content(content);

        xmlTextWriterEndElement(writer);

    }

    /**
     * charactersRoot
     * @param ch the characers
     * @param len number of characters
     *
     * SAX handler function for character handling at the root level.
     * Collect/write root level charactes.
     * 
     * Characters may be called multiple times in succession
     * in some cases the text may need to be gathered all at once
     * before output. Both methods are shown here although the delayed
     * output is used.
     *
     * Overide for desired behaviour.
     */
    /**command */
    virtual void  charactersRootcharactersRoot(const char*  ch, int  len) {


        //std::string content = "";
        content.append((const char *)ch, len);
        //write_content(content);

    }

    /**
     * charactersUnit
     * @param ch the characers
     * @param len number of characters
     *
     * SAX handler function for character handling within a unit.
     * Collect/write unit level charactes.
     * 
     * Characters may be called multiple times in succession
     * in some cases the text may need to be gathered all at once
     * before output. Both methods are shown here although the delayed
     * output is used.
     * 
     * Overide for desired behaviour.
     */
    /**command */
    virtual void  charactersUnitcharactersUnit(const char*  ch, int  len) {

        /*
            Characters may be called multiple times in succession
            in some cases the text may need to be gathered all at once
            before output. Both methods are shown here although the delayed
            output is used.
        */

        //std::string content = "";
        content.append((const char *)ch, len);
        //write_content(content);

    }

    /**
     * metaTag
     * @param localname the name of the element tag
     * @param prefix the tag prefix
     * @param URI the namespace of tag
     * @param num_namespaces number of namespaces definitions
     * @param namespaces the defined namespaces
     * @param nb_attributes the number of attributes on the tag
     * @param attributes list of attributes
     *
     * SAX handler function for meta tag.
     * Write out the meta tags.
     *
     * Overide for desired behaviour.
     */
    /**command collaborator */
    virtual void  metaTagmetaTag(const char*  localname, const char*  prefix, const char*  URI,
                           int  num_namespaces, const struct srcsax_namespace *  namespaces, int  nb_attributes,
                           const struct srcsax_attribute *  attributes) {

        // write out any buffered characters
        write_content(content);

        write_start_tag(localname, prefix, URI, num_namespaces, namespaces, nb_attributes, attributes);
        xmlTextWriterEndElement(writer);

    }

    /*
    // Not typically in srcML documents 
    virtual void comment(const char* value) {}
    virtual void cdataBlock(const char* value, int len) {}
    virtual void processingInstruction(const char* target, const char* data) {}
    */

#pragma GCC diagnostic pop

};

class NLContextPolicy : public srcSAXEventDispatch::EventListener, public srcSAXEventDispatch::PolicyDispatcher, public srcSAXEventDispatch::PolicyListener {
    public:
        struct NLContextData{
            NLContextData(){}
            /**command */
            void  clear(){
                category.clear();
                identifiername.clear();
            }
            std::string  category;
            std::string  identifiername;
        };
        NLContextData  data;
        ~NLContextPolicy(){}
        NLContextPolicy(std::initializer_list<srcSAXEventDispatch::PolicyListener *> listeners = {}): srcSAXEventDispatch::PolicyDispatcher(listeners ){
            sourcenlpolicy.AddListener(this);
            InitializeEventHandlers();
        }
        /**command collaborator */
        void  NotifyNotify(const PolicyDispatcher *  policy, const srcSAXEventDispatch::srcSAXEventContext &  ctx) override {
            sourcenlpdata = policy->Data<SourceNLPolicy::SourceNLData>();
            std::string  top;
            if(!context.empty()){
                top = context.top();
            }
            std::cerr<<"Output: "<<sourcenlpdata->identifiername<<" "<<sourcenlpdata->category<<" "<<top<<std::endl;
            //datatotest.push_back(SourceNLData);
        }
    protected:
        /**voidaccessor */
        void *  DataInner() const override {
            return new NLContextData(data);
        }
    private:
        SourceNLPolicy  sourcenlpolicy;
        SourceNLPolicy::SourceNLData*  sourcenlpdata;
        std::string  currentTypeName,  currentDeclName,  currentModifier,  currentSpecifier;
        std::stack<std::string>  context;
        /**command collaborator */
        void  InitializeEventHandlers(){
            using namespace srcSAXEventDispatch;
            openEventMap[ParserState::declstmt] = [this](srcSAXEventContext&  ctx) {
                ctx.dispatcher->AddListener(&sourcenlpolicy);
            };
            openEventMap[ParserState::whilestmt] = [this](srcSAXEventContext&  ctx) {
                std::cerr<<"seen while"<<std::endl;
                context.push("while");
            };
            openEventMap[ParserState::forstmt] = [this](srcSAXEventContext&  ctx) {
                std::cerr<<"seen for"<<std::endl;
                context.push("for");
            };
            openEventMap[ParserState::ifstmt] = [this](srcSAXEventContext&  ctx) {
                std::cerr<<"seen if"<<std::endl;
                context.push("if");
            };
            /*
            openEventMap[ParserState::whilestmt] = [this](srcSAXEventContext& ctx) {
                context.push("else if");
            };
            openEventMap[ParserState::whilestmt] = [this](srcSAXEventContext& ctx) {
                context.push("else");
            };*/
            closeEventMap[ParserState::declstmt] = [this](srcSAXEventContext&  ctx){
                ctx.dispatcher->RemoveListener(&sourcenlpolicy);
                data.clear();
            };
            closeEventMap[ParserState::whilestmt] = [this](srcSAXEventContext&  ctx){
                context.pop();
            };
            closeEventMap[ParserState::forstmt] = [this](srcSAXEventContext&  ctx){
                context.pop();
            };
            closeEventMap[ParserState::ifstmt] = [this](srcSAXEventContext&  ctx){
                context.pop();
            };

        }
};

class DeclTypePolicy : public srcSAXEventDispatch::EventListener, public srcSAXEventDispatch::PolicyDispatcher, public srcSAXEventDispatch::PolicyListener {
    public:
        struct DeclTypeData{
            DeclTypeData(): linenumber{0}, isConst{false}, isReference{false}, isPointer{false}, isStatic{false} {}
            /**command */
            void  clear(){
                nameoftype.clear();
                nameofidentifier.clear();
                namespaces.clear();
                linenumber = -1;
                isConst = false;
                isReference = false;
                isPointer = false;
                isStatic = false;
            }
            std::string  nameoftype;
            std::string  nameofidentifier;
            std::vector<std::string>  namespaces;
            int  linenumber;
            bool  isConst;
            bool  isReference;
            bool  isPointer;
            bool  isStatic;
        };
        DeclTypeData  data;
        ~DeclTypePolicy(){}
        DeclTypePolicy(std::initializer_list<srcSAXEventDispatch::PolicyListener *> listeners = {}): srcSAXEventDispatch::PolicyDispatcher(listeners ){
            InitializeEventHandlers();
        }
        /**collaborator */
        void  NotifyNotify(const PolicyDispatcher *  policy, const srcSAXEventDispatch::srcSAXEventContext &  ctx) override {} //doesn't use other parsers
    protected:
        /**voidaccessor */
        void *  DataInnerDataInner() const override {
            return new DeclTypeData(data);
        }
    private:
        std::string  currentTypeName,  currentDeclName,  currentModifier,  currentSpecifier;
        /**command collaborator */
        void  InitializeEventHandlers(){
            using namespace srcSAXEventDispatch;
            openEventMap[ParserState::op] = [this](srcSAXEventContext&  ctx){
                if(ctx.And({ParserState::type, ParserState::declstmt}) && ctx.Nor({ParserState::specifier, ParserState::modifier, ParserState::genericargumentlist})){
                    data.namespaces.push_back(ctx.currentToken);
                }
            };
            closeEventMap[ParserState::modifier] = [this](srcSAXEventContext&  ctx){
                if(ctx.IsOpen(ParserState::declstmt)){
                    if(currentModifier == "*"){
                        data.isPointer = true;
                    }
                    if(currentModifier == "&"){
                        data.isReference = true;
                    }
                }
            };

            closeEventMap[ParserState::decl] = [this](srcSAXEventContext&  ctx){
                if(ctx.And({ParserState::declstmt})){
                    data.linenumber = ctx.currentLineNumber;
                    data.nameofidentifier = currentDeclName;
                }
            };

            closeEventMap[ParserState::type] = [this](srcSAXEventContext&  ctx){
                if(ctx.And({ParserState::declstmt})){
                    data.nameoftype = currentTypeName;
                }
            };

            closeEventMap[ParserState::tokenstring] = [this](srcSAXEventContext&  ctx){
                //TODO: possibly, this if-statement is suppressing more than just unmarked whitespace. Investigate.
                if(!(ctx.currentToken.empty() || ctx.currentToken[0] == ' ')){
                    if(ctx.And({ParserState::name, ParserState::type, ParserState::decl, ParserState::declstmt}) && ctx.Nor({ParserState::specifier, ParserState::modifier, ParserState::genericargumentlist})){
                        currentTypeName = ctx.currentToken;
                    }
                    if(ctx.And({ParserState::name, ParserState::decl, ParserState::declstmt}) && 
                       ctx.Nor({ParserState::type, ParserState::index/*skip array portion*/, ParserState::argumentlist/*skip init list portion*/, ParserState::init, ParserState::specifier, ParserState::modifier})){
                        currentDeclName = ctx.currentToken;
                    }
                    if(ctx.And({ParserState::specifier, ParserState::decl, ParserState::declstmt})){
                        currentSpecifier = ctx.currentToken;
                    }
                    if(ctx.And({ParserState::modifier, ParserState::type, ParserState::declstmt})){
                        currentModifier = ctx.currentToken;
                    }
                }
            };
            closeEventMap[ParserState::declstmt] = [this](srcSAXEventContext&  ctx){
                NotifyAll(ctx);
                data.clear();
            };
            closeEventMap[ParserState::specifier] = [this](srcSAXEventContext&  ctx){
                if(ctx.IsOpen(ParserState::declstmt)){
                    if(currentSpecifier == "const"){
                        data.isConst = true;
                    }
                    if(currentSpecifier == "static"){
                        data.isStatic = true;
                    }
                }
                currentSpecifier.clear();
            };

        }
};

