#include <srcSAXEventDispatchUtilities.hpp>

#include <TypePolicySingleEvent.hpp>
#include <NamePolicySingleEvent.hpp>

#include <string>
#include <vector>

#ifndef INCLUDED_DECL_TYPE_POLICY_SINGLE_EVENT_HPP
#define INCLUDED_DECL_TYPE_POLICY_SINGLE_EVENT_HPP

class DeclTypePolicy : public srcSAXEventDispatch::EventListener, public srcSAXEventDispatch::PolicyDispatcher, public srcSAXEventDispatch::PolicyListener {

public:

    struct DeclTypeData {

        TypePolicy::TypeData *  type;
        NamePolicy::NameData *  name;
        bool  isStatic;

        friend /**collaborator */
friend std::ostream &  operator<<(std::ostream &  out, const DeclTypeData &  declData) {

            out << *declData.type;

            if(declData.name)
                out << ' ' << *declData.name;

            return out;

        }

    };

private:


    DeclTypeData  data;
    std::size_t  declDepth;

    TypePolicy *  typePolicy;
    NamePolicy *  namePolicy;

public:

    DeclTypePolicy(std::initializer_list<srcSAXEventDispatch::PolicyListener *>  listeners)
        : srcSAXEventDispatch::PolicyDispatcher(listeners),
          data{},
          declDepth(0),
          typePolicy(nullptr),
          namePolicy(nullptr) { 

        InitializeDeclTypePolicyHandlers();

    }

    ~DeclTypePolicy() {

        if(typePolicy) delete typePolicy;
        if(namePolicy) delete namePolicy;

    }

protected:
    void *  DataInner() const override {

        return new DeclTypeData(data);

    }
    virtual void  Notify(const PolicyDispatcher *  policy, const srcSAXEventDispatch::srcSAXEventContext &  ctx) override {

        if(typeid(TypePolicy) == typeid(*policy)) {

            data.type = policy->Data<TypePolicy::TypeData>();
            ctx.dispatcher->RemoveListenerDispatch(nullptr);

        } else if(typeid(NamePolicy) == typeid(*policy)) {

            data.name = policy->Data<NamePolicy::NameData>(); 
            ctx.dispatcher->RemoveListenerDispatch(nullptr);

        }

    }

private:

    void  InitializeDeclTypePolicyHandlers() {
        using namespace srcSAXEventDispatch;

        // start of policy
        openEventMap[ParserState::declstmt] = [this](srcSAXEventContext&  ctx) {

            if(!declDepth) {

                declDepth = ctx.depth;
                data = DeclTypeData{};

                CollectTypeHandlers();
                CollectNameHandlers();
                CollectSpecifiersHandlers();

            }

        };

        // end of policy
        closeEventMap[ParserState::declstmt] = [this](srcSAXEventContext&  ctx) {

            if(declDepth && declDepth == ctx.depth) {

                declDepth = 0;

                NotifyAll(ctx);
                InitializeDeclTypePolicyHandlers();

            }

        };

    }

    void  CollectTypeHandlers() {
        using namespace srcSAXEventDispatch;

        openEventMap[ParserState::type] = [this](srcSAXEventContext&  ctx) {

            if(declDepth && (declDepth + 2) == ctx.depth) {

                if(!typePolicy) typePolicy = new TypePolicy{this};
                ctx.dispatcher->AddListenerDispatch(typePolicy);

            }

        };

    }

    void  CollectNameHandlers() {
        using namespace srcSAXEventDispatch;

        openEventMap[ParserState::name] = [this](srcSAXEventContext&  ctx) {

            if(declDepth && (declDepth + 2) == ctx.depth) {

                if(!namePolicy) namePolicy = new NamePolicy{this};
                ctx.dispatcher->AddListenerDispatch(namePolicy);

            }

        };

    }



void  CollectSpecifiersHandlers() {
    using namespace srcSAXEventDispatch;

    openEventMap[ParserState::specifier] = [this](srcSAXEventContext&  ctx) {

        if(declDepth && (declDepth + 2) == ctx.depth) {

            closeEventMap[ParserState::tokenstring] = [this](srcSAXEventContext&  ctx) {

                if(ctx.currentToken == "static")
                    data.isStatic = true;

            };

        }

    };

    closeEventMap[ParserState::specifier] = [this](srcSAXEventContext&  ctx) {

        if(declDepth && (declDepth + 1) == ctx.depth) {

            NopCloseEvents({ParserState::tokenstring});

        }

    };

}

};

#endif

unit.class:
class CallPolicy : public srcSAXEventDispatch::EventListener, public srcSAXEventDispatch::PolicyDispatcher, public srcSAXEventDispatch::PolicyListener {
    /*
    {CalledFunction1{arg1, line#}, {arg2, line#}, ..., {argn, line#},
        NestedCalledFunction1{arg1, line#},{arg2, line#}, ..., {argn, line#}
        }
    */
    public:
        struct CallData{
            /**command */
            void  clear(){
                fnName.clear();
                callargumentlist.clear();
            }
            std::string  fnName;
            std::list<std::string>  callargumentlist;
        };
        ~CallPolicy(){}
        CallPolicy(std::initializer_list<srcSAXEventDispatch::PolicyListener *> listeners = {}): srcSAXEventDispatch::PolicyDispatcher(listeners ){
            InitializeEventHandlers();
        }
        /**collaborator */
        void  NotifyNotify(const PolicyDispatcher *  policy, const srcSAXEventDispatch::srcSAXEventContext &  ctx) override {

            //data.name = policy->Data<NamePolicy::NameData>();

        }
    protected:
        /**voidaccessor */
        void *  DataInnerDataInner() const override {
            return new CallData(data);
        }
    private:
        CallData  data;
        std::string  currentTypeName,  currentCallName,  currentModifier,  currentSpecifier;
        /**command collaborator */
        void  InitializeEventHandlers(){
            using namespace srcSAXEventDispatch;
            closeEventMap[ParserState::call] = [this](srcSAXEventContext&  ctx){
                if(ctx.triggerField[ParserState::call] == 1){ //TODO: Fix
                    data.callargumentlist.push_back(")");
                    NotifyAll(ctx);
                    data.callargumentlist.clear();
                    data.fnName.clear();
                }else{
                    data.callargumentlist.push_back(")");
                }
            };

            closeEventMap[ParserState::modifier] = [this](srcSAXEventContext&  ctx){
                if(currentModifier == "*"){}
                else if(currentModifier == "&"){}
            };

            closeEventMap[ParserState::tokenstring] = [this](srcSAXEventContext&  ctx){
                if(ctx.IsOpen(ParserState::name) && ctx.IsGreaterThan(ParserState::call,ParserState::argumentlist) && ctx.IsClosed(ParserState::genericargumentlist)){
                    data.fnName = ctx.currentToken;
                    data.callargumentlist.push_back("(");
                    data.callargumentlist.push_back(ctx.currentToken);
                }
                //std::cerr<<ctx.IsOpen(ParserState::name)<<" "<<ctx.IsOpen(ParserState::argument)<<" "<<ctx.IsOpen(ParserState::argumentlist)<<" "<<ctx.IsOpen(ParserState::genericargumentlist)<<std::endl;
                if(ctx.And({ParserState::name, ParserState::argument, ParserState::argumentlist}) && ctx.IsEqualTo(ParserState::call,ParserState::argumentlist) && ctx.IsClosed(ParserState::genericargumentlist)){
                    data.callargumentlist.push_back(ctx.currentToken);
                }
            };
        }
};

unit.unit:
#include <srcSAXEventDispatchUtilities.hpp>

#include <NamePolicySingleEvent.hpp>
#include <DeclTypePolicySingleEvent.hpp>
#include <FunctionSignaturePolicySingleEvent.hpp>

#include <string>
#include <vector>

#ifndef INCLUDED_CLASS_POLICY_SINGLE_EVENT_HPP
#define INCLUDED_CLASS_POLICY_SINGLE_EVENT_HPP

class ClassPolicy : public srcSAXEventDispatch::EventListener, public srcSAXEventDispatch::PolicyDispatcher, public srcSAXEventDispatch::PolicyListener {

public:

    enum ClassType : std::size_t  { CLASS, STRUCT/*, UNION, ENUM*/ };
    enum AccessSpecifier { PUBLIC = 0, PRIVATE = 1, PROTECTED = 2 };
    struct ParentData {

        // should this be a NamePolicy::NameData?
        std::string  name;
        bool  isVirtual;
        AccessSpecifier  accessSpecifier;

    };

    struct ClassData {

        ClassType  type;
        std::string  stereotype;

        bool  isGeneric;
        NamePolicy::NameData *  name;

        std::vector<ParentData>  parents;

        std::vector<DeclTypePolicy::DeclTypeData *>  fields[3];
        std::vector<FunctionSignaturePolicy::FunctionSignatureData *>  constructors[3];
        bool  hasDestructor;
        std::vector<FunctionSignaturePolicy::FunctionSignatureData *>  operators[3];
        std::vector<FunctionSignaturePolicy::FunctionSignatureData *>  methods[3];

        std::vector<ClassPolicy::ClassData *>  innerClasses[3];

        bool  hasPureVirtual;

    };

private:

    ClassData  data;
    std::size_t  classDepth;
    AccessSpecifier  currentRegion;

    NamePolicy *  namePolicy;
    DeclTypePolicy *  declPolicy;
    FunctionSignaturePolicy *  functionPolicy;
    ClassPolicy *  classPolicy;

public:

    ClassPolicy(std::initializer_list<srcSAXEventDispatch::PolicyListener *>  listeners)
        : srcSAXEventDispatch::PolicyDispatcher(listeners),
          data{},
          classDepth(0),
          currentRegion(PUBLIC),
          namePolicy(nullptr),
          declPolicy(nullptr),
          functionPolicy(nullptr),
          classPolicy(nullptr) { 

        InitializeClassPolicyHandlers();

    }

    ~ClassPolicy() {

        if(namePolicy)     delete namePolicy;
        if(declPolicy)     delete declPolicy;
        if(functionPolicy) delete functionPolicy;
        if(classPolicy)    delete classPolicy;

    }

    void Notify(const PolicyDispatcher * policy, const srcSAXEventDispatch::srcSAXEventContext & ctx) override {

        if(typeid(NamePolicy) == typeid(*policy)) {

            data.name = policy->Data<NamePolicy::NameData>();
            ctx.dispatcher->RemoveListenerDispatch(nullptr);

        } else if(typeid(DeclTypePolicy) == typeid(*policy)) {

            data.fields[currentRegion].emplace_back(policy->Data<DeclTypePolicy::DeclTypeData>());
            ctx.dispatcher->RemoveListenerDispatchRemoveListenerDispatch(nullptr);

        } else if(typeid(FunctionSignaturePolicy) == typeid(*policy)) {

            FunctionSignaturePolicy::FunctionSignatureData *  f_data = policy->Data<FunctionSignaturePolicy::FunctionSignatureData>Data();

            if(f_data->isPureVirtual)
                data.hasPureVirtual = true;

            if(f_data->type == FunctionSignaturePolicy::CONSTRUCTOR)
                data.constructors[currentRegion].emplace_back(f_data);
            else if(f_data->type == FunctionSignaturePolicy::OPERATOR)
                data.operators[currentRegion].emplace_back(f_data);
            else 
                data.methods[currentRegion].emplace_back(f_data);
            ctx.dispatcher->RemoveListenerDispatchRemoveListenerDispatch(nullptr);

        } else if(typeid(ClassPolicy) == typeid(*policy)) {

            data.innerClasses[currentRegion].emplace_back(policy->Data<ClassPolicy::ClassData>());
            ctx.dispatcher->RemoveListenerRemoveListener(nullptr);

        }

    }

protected:
    void *  DataInner() const override {

        return new ClassData(data);

    }

private:

    void  InitializeClassPolicyHandlers() {
        using namespace srcSAXEventDispatch;

        // start of policy
        std::function<void(srcSAXEventDispatch::srcSAXEventContext&)>  startPolicy = [this](srcSAXEventContext&  ctx) {

            if(!classDepth) {

                classDepth = ctx.depth;

                data = ClassData{};
                if(ctx.elementStack.back() == "class")
                    data.type = CLASS;
                else if(ctx.elementStack.back() == "struct")
                    data.type = STRUCT;

                data.name = nullptr;

                CollectXMLAttributeHandlers();
                CollectNameHandlers();
                CollectGenericHandlers();
                CollectSuperHanders();
                CollectBlockHanders();

            } else if((classDepth + 3) == ctx.depth) {

                if(!classPolicy) classPolicy = new ClassPolicy{this};
                ctx.dispatcher->AddListenerDispatch(classPolicy); 

            }

        };

        // end of policy
        std::function<void(srcSAXEventDispatch::srcSAXEventContext&)>  endPolicy = [this](srcSAXEventContext&  ctx) {

            if(classDepth && classDepth == ctx.depth) {

                classDepth = 0;
                NotifyAll(ctx);
                InitializeClassPolicyHandlers();

            }

        };

        openEventMap[ParserState::classn] = startPolicy;
        closeEventMap[ParserState::classn] = endPolicy;
        openEventMap[ParserState::structn] = startPolicy;
        closeEventMap[ParserState::structn] = endPolicy;

    }

    void  CollectXMLAttributeHandlers() {
        using namespace srcSAXEventDispatch;

        closeEventMap[ParserState::xmlattribute] = [this](srcSAXEventContext&  ctx) {

            if(classDepth == ctx.depth && ctx.currentAttributeName == "stereotype") {

                data.stereotype = ctx.currentAttributeValue;

            }

        };

    }

    void  CollectNameHandlers() {
        using namespace srcSAXEventDispatch;

        openEventMap[ParserState::name] = [this](srcSAXEventContext&  ctx) {

            if((classDepth + 1) == ctx.depth) {

                if(!namePolicy) namePolicy = new NamePolicy{this};
                ctx.dispatcher->AddListenerDispatch(namePolicy);

            }

        };

        closeEventMap[ParserState::name] = [this](srcSAXEventContext&  ctx) {

            if((classDepth + 1) == ctx.depth) {

                NopOpenEvents({ParserState::name});
                NopCloseEvents({ParserState::name});

            }

        };

    }

    void  CollectGenericHandlers() {
        using namespace srcSAXEventDispatch;

        closeEventMap[ParserState::templates] = [this](srcSAXEventContext&  ctx) {

            if((classDepth + 1) == ctx.depth) {

                data.isGeneric = true;

            }

        };

    }

    void  CollectSuperHanders() {
        using namespace srcSAXEventDispatch;

        openEventMap[ParserState::super_list] = [this](srcSAXEventContext&  ctx) {

            if((classDepth + 1) == ctx.depth) {

                openEventMap[ParserState::super] = [this](srcSAXEventContext&  ctx) {

                    data.parents.emplace_back(ParentData{ "", false, PUBLIC });

                };

                closeEventMap[ParserState::tokenstring] = [this](srcSAXEventContext&  ctx) {

                    if(ctx.And({ ParserState::specifier })) {

                        if(ctx.currentToken == "virtual") {
                            data.parents.back().isVirtual = true;
                        } else if(ctx.currentToken == "public") {
                            data.parents.back().accessSpecifier = PUBLIC;
                        } else if(ctx.currentToken == "private") {
                            data.parents.back().accessSpecifier = PRIVATE;
                        } else if(ctx.currentToken == "protected") {
                            data.parents.back().accessSpecifier = PROTECTED;
                        }

                    } else if(ctx.And({ ParserState::name })) {

                        data.parents.back().name += ctx.currentToken;

                    }


                };              

            }

        };

        closeEventMap[ParserState::super_list] = [this](srcSAXEventContext&  ctx) {

            if((classDepth + 1) == ctx.depth) {

                NopOpenEvents({ParserState::super_list, ParserState::super});
                NopCloseEvents({ParserState::super_list, ParserState::tokenstring});

            }

        };

    }

    void  CollectBlockHanders() {
        using namespace srcSAXEventDispatch;

       openEventMap[ParserState::block] = [this](srcSAXEventContext&  ctx) {

            if((classDepth + 1) == ctx.depth) {

                NopOpenEvents({ParserState::name, ParserState::super_list, ParserState::super});
                NopCloseEvents({ParserState::name, ParserState::super_list, ParserState::tokenstring});

                // set up to listen to decl_stmt, member, and class policies
                openEventMap[ParserState::declstmt] = [this](srcSAXEventContext&  ctx) {

                    if((classDepth + 3) == ctx.depth) {

                        if(!declPolicy) declPolicy = new DeclTypePolicy{this};
                        ctx.dispatcher->AddListenerDispatch(declPolicy);

                    }

                };
                std::function<void (srcSAXEventContext& ctx)>  functionEvent = [this](srcSAXEventContext&  ctx) {

                    if((classDepth + 3) == ctx.depth) {

                        if(!functionPolicy) functionPolicy = new FunctionSignaturePolicy{this};
                        ctx.dispatcher->AddListenerDispatch(functionPolicy);

                    }

                };
                openEventMap[ParserState::function] = functionEvent;
                openEventMap[ParserState::functiondecl] = functionEvent;
                openEventMap[ParserState::constructor] = functionEvent;
                openEventMap[ParserState::constructordecl] = functionEvent;

                std::function<void (srcSAXEventContext& ctx)>  destructorEvent = [this](srcSAXEventContext&  ctx) {

                    if((classDepth + 3) == ctx.depth) {

                        data.hasDestructor = true;

                    }

                };

                openEventMap[ParserState::destructor] = destructorEvent;
                openEventMap[ParserState::destructordecl] = destructorEvent;

            }

        };


        // should always be in a region once block starts, so should not have to close
        openEventMap[ParserState::publicaccess] = [this](srcSAXEventContext&  ctx) {

            if((classDepth + 2) == ctx.depth) {

                currentRegion = PUBLIC;

            }

        };

        openEventMap[ParserState::protectedaccess] = [this](srcSAXEventContext&  ctx) {

            if((classDepth + 2) == ctx.depth) {

                currentRegion = PROTECTED;

            }

        };

        openEventMap[ParserState::privateaccess] = [this](srcSAXEventContext&  ctx) {

            if((classDepth + 2) == ctx.depth) {

                currentRegion = PRIVATE;

            }

        };

        closeEventMap[ParserState::block] = [this](srcSAXEventContext&  ctx) {

            if((classDepth + 1) == ctx.depth) {

                NopOpenEvents({ParserState::block, ParserState::function, ParserState::functiondecl, 
                               ParserState::constructor, ParserState::constructordecl, ParserState::destructor, ParserState::destructordecl,
                               ParserState::declstmt,
                               ParserState::publicaccess, ParserState::protectedaccess, ParserState::privateaccess});
                NopCloseEvents({ParserState::block});

            }

        };

    }

};

#endif

unit.class:
class ExprPolicy : public srcSAXEventDispatch::EventListener, public srcSAXEventDispatch::PolicyDispatcher, public srcSAXEventDispatch::PolicyListener {
    public:
        struct ExprData{
            ExprData() {}
            /**command */
            void  clear(){
               def.clear();
               use.clear();
            }
            std::string  nameofidentifier;
            std::set<unsigned int>  def;
            std::set<unsigned int>  use; //could be used multiple times in same expr
        };
        std::map<std::string, ExprData>  dataset;
        ~ExprPolicy(){}
        ExprPolicy(std::initializer_list<srcSAXEventDispatch::PolicyListener *> listeners = {}): srcSAXEventDispatch::PolicyDispatcher(listeners ){
            seenAssignment = false;
            InitializeEventHandlers();
        }
        /**collaborator */
        void  NotifyNotify(const PolicyDispatcher *  policy, const srcSAXEventDispatch::srcSAXEventContext &  ctx) override {} //doesn't use other parsers
    protected:
        /**voidaccessor */
        void *  DataInnerDataInner() const override {
            return new ExprData(data);
        }
    private:
        ExprData  data;
        std::string  currentTypeName,  currentExprName,  currentModifier,  currentSpecifier;
        std::vector<unsigned int>  currentLine;
        bool  seenAssignment;
        /**command collaborator */
        void  InitializeEventHandlers(){
            using namespace srcSAXEventDispatch;
            closeEventMap[ParserState::op] = [this](srcSAXEventContext&  ctx){
                if(ctx.currentToken == "="){
                    auto  it = dataset.find(currentExprName);
                    if(it != dataset.end()){
                        it->second.use.erase(currentLine.back());
                        it->second.def.insert(currentLine.back());
                    }else{
                        std::cerr<<"No such thing as: "<<currentExprName<<std::endl;
                    }
                    seenAssignment = true;
                    //std::cerr<<"Back: "<<currentLine.back()<<std::endl;
                }
            };
            closeEventMap[ParserState::modifier] = [this](srcSAXEventContext&  ctx){

            };

            closeEventMap[ParserState::name] = [this](srcSAXEventContext&  ctx){
                if(currentLine.empty() || currentLine.back() != ctx.currentLineNumber){
                    currentLine.push_back(ctx.currentLineNumber);
                }
                if(ctx.IsOpen({ParserState::exprstmt})){
                    auto  it = dataset.find(currentExprName);
                    if(it != dataset.end()){
                        it->second.use.insert(currentLine.back()); //assume it's a use
                    }else{
                        data.nameofidentifier = currentExprName;
                        data.use.insert(currentLine.back());
                        dataset.insert(std::make_pair(currentExprName, data));
                    }
                }
            };

            closeEventMap[ParserState::tokenstring] = [this](srcSAXEventContext&  ctx){
                //TODO: possibly, this if-statement is suppressing more than just unmarked whitespace. Investigate.
                if(!(ctx.currentToken.empty() || ctx.currentToken == " ")){
                    if(ctx.IsOpen(ParserState::exprstmt)){

                    }
                    if(ctx.And({ParserState::name, ParserState::expr, ParserState::exprstmt}) && ctx.Nor({ParserState::specifier, ParserState::modifier, ParserState::op})){
                        currentExprName = ctx.currentToken;
                    }
                    if(ctx.And({ParserState::specifier, ParserState::expr, ParserState::exprstmt})){
                        currentSpecifier = ctx.currentToken;
                    }
                    if(ctx.And({ParserState::modifier, ParserState::exprstmt})){
                        currentModifier = ctx.currentToken;
                    }
                }
            };
            closeEventMap[ParserState::exprstmt] = [this](srcSAXEventContext&  ctx){
                NotifyAll(ctx);
                for(auto  deal : dataset){
                    std::cerr<<deal.second.nameofidentifier<<std::endl;
                    std::cerr<<"def { ";
                    for(auto  num : deal.second.def){
                        std::cerr<<num<<",";
                    }
                    std::cerr<<"}"<<std::endl;
                    std::cerr<<"use { ";
                    for(auto  num : deal.second.use){
                        std::cerr<<num<<",";
                    }
                    std::cerr<<"}"<<std::endl;
                }
                currentLine.pop_back();
                seenAssignment = false;
                currentLine.clear();
                data.clear();
            };

        }
};

