#include <TemplateArgumentPolicySingleEvent.hpp>

#include <NamePolicySingleEvent.hpp>

std::ostream &  operator<<(std::ostream &  out, const TemplateArgumentPolicy::TemplateArgumentData &  argumentData) {

    for(std::size_t  pos = 0; pos < argumentData.data.size(); ++pos) {

        if(pos != 0)
            out << ' ';

        const std::pair<void *, TemplateArgumentPolicy::TemplateArgumentType> &  element = argumentData.data[pos];
        if(element.second == TemplateArgumentPolicy::NAME)
            out << *static_cast<NamePolicy::NameData *>(element.first);
        else if(element.second == TemplateArgumentPolicy::POINTER)
            out << '*';
        else if(element.second == TemplateArgumentPolicy::REFERENCE)
            out << '&';
        else if(element.second == TemplateArgumentPolicy::RVALUE)
            out << "&&";
        else
            out << *static_cast<std::string *>(element.first);

    }

    return out;

}

TemplateArgumentPolicy::TemplateArgumentPolicy(std::initializer_list<srcSAXEventDispatch::PolicyListener *>  listeners)
    : srcSAXEventDispatch::PolicyDispatcher(listeners),
      data{},
      argumentDepth(0),
      namePolicy(nullptr) {

    InitializeTemplateArgumentPolicyHandlers();

}

TemplateArgumentPolicy::~TemplateArgumentPolicy() {

    if(namePolicy) delete namePolicy;

}

/**command collaborator */
void  TemplateArgumentPolicy::Notify(const PolicyDispatcher *  policy, const srcSAXEventDispatch::srcSAXEventContext &  ctx) {

    data.data.back().first = policy->Data<NamePolicy::NameData>Data();
    ctx.dispatcher->RemoveListenerDispatchRemoveListenerDispatch(nullptr);

}

/**voidaccessor */
void *  TemplateArgumentPolicy::DataInner() const {
    return new TemplateArgumentPolicy::TemplateArgumentData(data);
}

/**command collaborator */
void  TemplateArgumentPolicy::InitializeTemplateArgumentPolicyHandlers() {
    using namespace srcSAXEventDispatch;

    // start of policy
    openEventMap[ParserState::argument] = [this](srcSAXEventContext&  ctx) {

        if(!argumentDepth) {

            argumentDepth = ctx.depth;
            data = TemplateArgumentPolicy::TemplateArgumentData{};

            CollectNamesHandler();
            CollectOthersHandler();

        }

    };

    // end of policy
    closeEventMap[ParserState::argument] = [this](srcSAXEventContext&  ctx) {

        if(argumentDepth && argumentDepth == ctx.depth) {

            argumentDepth = 0;

            NotifyAll(ctx);
            InitializeTemplateArgumentPolicyHandlers();

        }

    };

}

/**command collaborator */
void  TemplateArgumentPolicy::CollectNamesHandler() {
    using namespace srcSAXEventDispatch;

    openEventMap[ParserState::name] = [this](srcSAXEventContext&  ctx) {

        // C++ has depth of 2 others 1
        std::size_t  elementStackSize = ctx.elementStack.size();
        if(     argumentDepth && (((argumentDepth + 2) == ctx.depth && elementStackSize > 1 && ctx.elementStack[elementStackSize - 2] == "expr")
            || (argumentDepth + 1) == ctx.depth)) {

            data.data.push_back(std::make_pair(nullptr, TemplateArgumentPolicy::NAME));
            if(!namePolicy) namePolicy = new NamePolicy{this};
            ctx.dispatcher->AddListenerDispatch(namePolicy);

        }

    };

}

/**command collaborator */
void  TemplateArgumentPolicy::CollectOthersHandler() {
    using namespace srcSAXEventDispatch;

    openEventMap[ParserState::literal] = [this](srcSAXEventContext&  ctx) {

        // C++ has depth of 2 others 1
        std::size_t  elementStackSize = ctx.elementStack.size();
        if(     argumentDepth && (((argumentDepth + 2) == ctx.depth && elementStackSize > 1 && ctx.elementStack[elementStackSize - 2] == "expr")
            || (argumentDepth + 1) == ctx.depth)) {

            data.data.push_back(std::make_pair(new std::string(), LITERAL));
            closeEventMap[ParserState::tokenstring] = [this](srcSAXEventContext&  ctx) {
                (*static_cast<std::string *>(data.data.back().first)) += ctx.currentToken;
            };

        }

    };

    closeEventMap[ParserState::literal] = [this](srcSAXEventContext&  ctx) {

        if(     argumentDepth && (((argumentDepth + 2) == ctx.depth && ctx.elementStack.back() == "expr")
            || (argumentDepth + 1) == ctx.depth)) {

            NopCloseEvents({ParserState::tokenstring});

        }

    };

    openEventMap[ParserState::op] = [this](srcSAXEventContext&  ctx) {

        // C++ has depth of 2 others 1
        std::size_t  elementStackSize = ctx.elementStack.size();
        if(     argumentDepth && (((argumentDepth + 2) == ctx.depth && elementStackSize > 1 && ctx.elementStack[elementStackSize - 2] == "expr")
            || (argumentDepth + 1) == ctx.depth)) {

            data.data.push_back(std::make_pair(new std::string(), OPERATOR));
            closeEventMap[ParserState::tokenstring] = [this](srcSAXEventContext&  ctx) {
                (*static_cast<std::string *>(data.data.back().first)) += ctx.currentToken;
            };

        }

    };

    closeEventMap[ParserState::op] = [this](srcSAXEventContext&  ctx) {

        if(     argumentDepth && (((argumentDepth + 2) == ctx.depth && ctx.elementStack.back() == "expr")
            || (argumentDepth + 1) == ctx.depth)) {

            NopCloseEvents({ParserState::tokenstring});

        }

    };

    openEventMap[ParserState::modifier] = [this](srcSAXEventContext&  ctx) {

        // C++ has depth of 2 others 1
        std::size_t  elementStackSize = ctx.elementStack.size();
        if(     argumentDepth && (((argumentDepth + 2) == ctx.depth && elementStackSize > 1 && ctx.elementStack[elementStackSize - 2] == "expr")
            || (argumentDepth + 1) == ctx.depth)) {

            data.data.push_back(std::make_pair(nullptr, MODIFIER));
            closeEventMap[ParserState::tokenstring] = [this](srcSAXEventContext&  ctx) {

                if(ctx.currentToken == "*")
                    data.data.back().second = POINTER;
                else if(ctx.currentToken == "&")
                    data.data.back().second = REFERENCE;
                else if(ctx.currentToken == "&&")
                    data.data.back().second = RVALUE;

            };

        }

    };

    closeEventMap[ParserState::modifier] = [this](srcSAXEventContext&  ctx) {

        if(     argumentDepth && (((argumentDepth + 2) == ctx.depth && ctx.elementStack.back() == "expr")
            || (argumentDepth + 1) == ctx.depth)) {

            NopCloseEvents({ParserState::tokenstring});

        }

    };

    openEventMap[ParserState::call] = [this](srcSAXEventContext&  ctx) {

        // C++ has depth of 2 others 1
        std::size_t  elementStackSize = ctx.elementStack.size();
        if(     argumentDepth && (((argumentDepth + 2) == ctx.depth && elementStackSize > 1 && ctx.elementStack[elementStackSize - 2] == "expr")
            || (argumentDepth + 1) == ctx.depth)) {

            data.data.push_back(std::make_pair(new std::string(), CALL));
            closeEventMap[ParserState::tokenstring] = [this](srcSAXEventContext&  ctx) {
                (*static_cast<std::string *>(data.data.back().first)) += ctx.currentToken;
            };

        }

    };

    closeEventMap[ParserState::call] = [this](srcSAXEventContext&  ctx) {

        if(     argumentDepth && (((argumentDepth + 2) == ctx.depth && ctx.elementStack.back() == "expr")
            || (argumentDepth + 1) == ctx.depth)) {

            NopCloseEvents({ParserState::tokenstring});

        }

    };

}

unit.namespace:
namespace srcSAXEventDispatch {
    template <typename ... policies>
    class srcSAXSingleEventDispatcher : public srcSAXEventDispatcher<policies...> {

    private:
        bool  dispatched;

    public:

       srcSAXSingleEventDispatcher(PolicyListener *  listener) : srcSAXEventDispatcher<policies...>(listener), dispatched(false) {}
        /**command collaborational-command collaborator */
        virtual void  AddListener(EventListener *  listener) override {
            EventDispatcher::elementListeners.back()->SetDispatched(false);
            EventDispatcher::elementListeners.push_back(listener);
        }
        /**set collaborator */
        virtual void  AddListenerDispatch(EventListener *  listener) override {
            AddListener(listener);
            dispatched = false;
        }
        /**command collaborator stateless */
        virtual void  AddListenerNoDispatch(EventListener *  listener) override {
            AddListener(listener);
        }
        /**command collaborational-command collaborator */
        virtual void  RemoveListener(EventListener *  listener) override {
            EventDispatcher::elementListeners.back()->SetDispatched(false);
            EventDispatcher::elementListeners.pop_back();
        }
        /**set collaborator */
        virtual void  RemoveListenerDispatch(EventListener *  listener) override {
            RemoveListener(listener);
            dispatched = false;
        }
        /**command collaborator stateless */
        virtual void  RemoveListenerNoDispatch(EventListener *  listener) override {
            RemoveListener(listener);
        }
    protected:
        /**command collaborator */
        virtual void  DispatchEvent(srcSAXEventDispatch::ParserState  pstate, srcSAXEventDispatch::ElementState  estate) override {

            while(!dispatched) {

                dispatched = true;

                EventDispatcher::elementListeners.back()->HandleEvent(pstate, estate, EventDispatcher::ctx);
                EventDispatcher::elementListeners.back()->SetDispatched(false);

            }

            dispatched = false;

        }

    };

}

namespace srcSAXEventDispatch{
    class EventDispatcher;            
    enum ElementState {open, close};
    enum ParserState {decl, expr, parameter, declstmt, exprstmt, parameterlist, 
        argumentlist, argumentlisttemplate, call, templates, ctrlflow, endflow, genericargumentlist,
        name, function, functiondecl, constructor, constructordecl, destructordecl, destructor,
        argument, index, block, type, init, op, literal, modifier, memberlist, classn, structn,
        super_list, super, publicaccess, privateaccess, protectedaccess, preproc, whilestmt, forstmt, 
        ifstmt, nonterminal, macro, classblock, functionblock, ifblock, whileblock, forblock, specifier, typedefexpr,
        userdefined, snoun, propersnoun, spronoun, sadjective, sverb,

        // do not put anything after these
        xmlattribute, tokenstring, empty, MAXENUMVALUE = empty};
    class srcSAXEventContext {
        public:
            srcSAXEventContext() = delete;
            srcSAXEventContext(EventDispatcher *  dispatcher, const std::vector<std::string> &  elementStack)
                : dispatcher(dispatcher),
                  elementStack(elementStack),
                  triggerField(std::vector<unsigned short int>(MAXENUMVALUE, 0)),
                  depth(0),
                  isOperator(false),
                  currentLineNumber{0} {}

            EventDispatcher *  dispatcher;
            const std::vector<std::string> &  elementStack;
            std::vector<int>  genericDepth;
            unsigned int  currentLineNumber;
            std::vector<unsigned short int>  triggerField;
            std::string  currentFilePath,  currentFileName,  currentFileLanguage,  currentsrcMLRevision,
                         currentTag,  currentToken,  currentAttributeName,  currentAttributeValue;
            std::size_t  depth;
            bool  isOperator;

        public:
            /**predicate collaborator */
            inline bool  And(std::vector<ParserState>  vec) const{
                for(auto  field : vec){
                    if(triggerField[field]) continue;
                    else return false;
                }
                return true;
            }
            /**predicate collaborator */
            inline bool  Nand(std::vector<ParserState>  vec) const{
                for(auto  field : vec){
                    if(triggerField[field]) return false;
                    else continue;
                }
                return true;
            }
            /**predicate collaborator */
            inline bool  Or(std::vector<ParserState>  vec) const{
                for(auto  field : vec){
                    if(triggerField[field]) return true;
                    else continue;
                }
                return false;
            }
            /**predicate collaborator */
            inline bool  Nor(std::vector<ParserState>  vec) const{
                for(auto  field : vec){
                    if(triggerField[field]) return false;
                    else continue;
                }
                return true;
            }
            /**predicate collaborator */
            inline bool  IsEqualTo(ParserState  lhs, ParserState  rhs) const{
                return triggerField[lhs] == triggerField[rhs] ? true : false;
            }
            /**predicate collaborator */
            inline bool  IsGreaterThan(ParserState  lhs, ParserState  rhs) const{
                return triggerField[lhs] > triggerField[rhs] ? true : false;
            }
            /**predicate collaborator */
            inline bool  IsGreaterThanOrEqualTo(ParserState  lhs, ParserState  rhs) const{
                return triggerField[lhs] >= triggerField[rhs] ? true : false;   
            }
            /**predicate collaborator */
            inline bool  IsLessThan(ParserState  lhs, ParserState  rhs) const{
                return triggerField[lhs] < triggerField[rhs] ? true : false;    
            }
            /**predicate collaborator */
            inline bool  IsLessThanOrEqualTo(ParserState  lhs, ParserState  rhs) const{
                return triggerField[lhs] <= triggerField[rhs] ? true : false;   
            }
            /**predicate collaborator */
            inline bool  IsOpen(ParserState  field) const{
                if(triggerField[field]) return true;
                else return false;
            }
            /**predicate collaborator */
            inline bool  IsClosed(ParserState  field) const{
                if(triggerField[field]) return false;
                else return true;
            }
    };

    class EventListener {
        typedef std::unordered_map<srcSAXEventDispatch::ParserState, std::function<void(srcSAXEventDispatch::srcSAXEventContext&)>, std::hash<int>>  EventMap;
        protected:
           bool  dispatched;
           EventMap  openEventMap,  closeEventMap;


        public:

            EventListener() : dispatched(false) {
                DefaultEventHandlers();
            }

            /**set */
            void  SetDispatched(bool  isDispatched) { dispatched = isDispatched; }

            /**get collaborator */
            virtual const EventMap &  GetOpenEventMap() const { return openEventMap; }
            /**get collaborator */
            virtual const EventMap &  GetCloseEventMap() const { return closeEventMap; }

            /**set */
            virtual void  HandleEvent() { dispatched = true; }
            /**command collaborator */
            virtual void  HandleEvent(srcSAXEventDispatch::ParserState  pstate, srcSAXEventDispatch::ElementState  estate, srcSAXEventDispatch::srcSAXEventContext&  ctx) {

                if(dispatched) return;

                dispatched = true;

                switch(estate){

                    case srcSAXEventDispatch::ElementState::open: {
                        auto  event = openEventMap.find(pstate);
                        if(event != openEventMap.end()){
                            event->second(ctx);
                        }
                        break;
                    }

                    case srcSAXEventDispatch::ElementState::close: {
                        auto  event = closeEventMap.find(pstate);
                        if(event != closeEventMap.end()){
                            event->second(ctx);
                        }
                        break;
                    }

                    default:
                        throw std::runtime_error("Something went terribly, terribly wrong");

                }

            }

        protected:
            /**collaborator */
            void  NopOpenEvents(std::initializer_list<ParserState>  states) {

                for(ParserState  state : states) {

                    openEventMap[state] = [this](const srcSAXEventContext&  ctx) {};

                }

            }            
            /**collaborator */
            void  NopCloseEvents(std::initializer_list<ParserState>  states) {

                for(ParserState  state : states) {

                    closeEventMap[state] = [this](const srcSAXEventContext&  ctx) {};

                }

            } 

        private:

            /**command */
            void  DefaultEventHandlers() {
                using namespace srcSAXEventDispatch;

                NopOpenEvents({
                    ParserState::declstmt,
                    ParserState::exprstmt,
                    ParserState::parameterlist,
                    ParserState::ifstmt,
                    ParserState::forstmt,
                    ParserState::whilestmt,
                    ParserState::templates,
                    ParserState::argumentlist,
                    ParserState::genericargumentlist,
                    ParserState::call,
                    ParserState::function,
                    ParserState::constructor,
                    ParserState::functiondecl,
                    ParserState::destructordecl,
                    ParserState::constructordecl,
                    ParserState::classn,
                    ParserState::structn,
                    ParserState::publicaccess,
                    ParserState::protectedaccess,
                    ParserState::privateaccess,
                    ParserState::destructor,
                    ParserState::parameter,
                    ParserState::memberlist,
                    ParserState::index,
                    ParserState::op,
                    ParserState::block,
                    ParserState::init,
                    ParserState::argument,
                    ParserState::literal,
                    ParserState::modifier,
                    ParserState::decl,
                    ParserState::type,
                    ParserState::typedefexpr,
                    ParserState::expr,
                    ParserState::name,
                    ParserState::macro,
                    ParserState::specifier,
                    ParserState::snoun,
                    ParserState::propersnoun,
                    ParserState::sadjective,
                    ParserState::spronoun,
                    ParserState::sverb,
                });

                NopCloseEvents({
                    ParserState::declstmt,
                    ParserState::exprstmt,
                    ParserState::parameterlist,
                    ParserState::ifstmt,
                    ParserState::forstmt,
                    ParserState::whilestmt,
                    ParserState::templates,
                    ParserState::argumentlist,
                    ParserState::genericargumentlist,
                    ParserState::call,
                    ParserState::function,
                    ParserState::constructor,
                    ParserState::destructor,
                    ParserState::functiondecl,
                    ParserState::constructordecl,
                    ParserState::destructordecl,
                    ParserState::classn,
                    ParserState::structn,
                    ParserState::publicaccess,
                    ParserState::protectedaccess,                  
                    ParserState::privateaccess,
                    ParserState::parameter,
                    ParserState::memberlist,
                    ParserState::index,
                    ParserState::op,
                    ParserState::block,
                    ParserState::init,
                    ParserState::argument,
                    ParserState::literal,
                    ParserState::modifier,
                    ParserState::decl,
                    ParserState::type,
                    ParserState::typedefexpr,
                    ParserState::expr,
                    ParserState::name,
                    ParserState::macro,
                    ParserState::tokenstring,
                    ParserState::specifier,
                    ParserState::snoun,
                    ParserState::propersnoun,
                    ParserState::sadjective,
                    ParserState::spronoun,
                    ParserState::sverb,
                });

        }

    };
    class EventDispatcher {
    public:
        virtual void  AddListener(EventListener*  l) = 0;
        virtual void  AddListenerDispatch(EventListener*  listener) = 0;
        virtual void  AddListenerNoDispatch(EventListener*  listener) = 0;
        virtual void  RemoveListener(EventListener*  l) = 0;
        virtual void  RemoveListenerDispatch(EventListener*  listener) = 0;
        virtual void  RemoveListenerNoDispatch(EventListener*  listener) = 0;
    protected:
        srcSAXEventContext  ctx;
        std::list<EventListener*>  elementListeners;

        EventDispatcher(const std::vector<std::string> &  elementStack)
            : elementListeners(), ctx(this, elementStack) {}
        virtual void  DispatchEvent(ParserState , ElementState ) = 0;
    };
    class PolicyDispatcher;
    class PolicyListener{

        public:

            PolicyListener() {}
            virtual void  Notify(const PolicyDispatcher *  policy, const srcSAXEventContext &  ctx) = 0;

        };
    class PolicyDispatcher{
    public:
        PolicyDispatcher(std::initializer_list<PolicyListener *>  listeners) : policyListeners(listeners){}
        /**command collaborator stateless */
        virtual void  AddListener(PolicyListener*  listener){
            policyListeners.push_back(listener);
        }
        /**command collaborator */
        virtual void  RemoveListener(PolicyListener*  listener){
            policyListeners.erase(std::find(policyListeners.begin(), policyListeners.end(), listener));
        }

        /**property collaborator */
        template<typename  T>
        T *  Data() const {

            return static_cast<T *>(DataInner());

        }

    protected:
        std::list<PolicyListener*>  policyListeners;
        virtual void *  DataInner() const = 0;
        /**command collaborator */
        virtual void  NotifyAll(const srcSAXEventContext &  ctx) {
            std::cerr<<"Size: "<<policyListeners.size()<<std::endl;
            for(std::list<PolicyListener*>::iterator  listener = policyListeners.begin(); listener != policyListeners.end(); ++listener){
               std::cerr<<"Listen man"<<std::endl;
                (*listener)->Notify(this, ctx);
            }

        }

    };
}

