                } },
                { "specifier", [this](){
                    DispatchEvent(ParserState::specifier, ElementState::close);
                    --ctx.triggerField[ParserState::specifier];
                } },
                { "noun", [this](){
                    --ctx.triggerField[ParserState::snoun];
                    DispatchEvent(ParserState::snoun, ElementState::close);
